    ,
      cs: "kotrč kadeřavý",
      es: 'seta coliflor',
      nl: 'Grote sponszwam',
      da: 'kruset blomkålssvamp',
      no: 'blomkålsopp',
      sv: 'blomkålssvamp',
      ru: "спарассис курчавый",
      uk: "спарасис кучерявий",
