      nl: "traliestinkzwam",
      fr: "clathre rouge",
      de: "Roter Gitterling",
      hu: "piros kosárgomba",
      ja: "アカカゴタケ",
      ko: "붉은바구니버섯",
      no: "gittersopp",
      pl: "okratek czerwony",
      pt: "clatro-vermelho",
