      lv: "noliektā sēntiņa",
      en: "clustered bonnet",
      sk: "prilbička naklonená",
      zh: "弯柄小菇",
      cs: "helmovka leponohá",
      nl: "fraaisteelmycena",
      et: "kobarmütsik",
      fi: "tammihiippo",
      fr: "mycène inclinée",
      de: "Buntstieliger Helmling",
      hu: "cifra kígyógomba",
      lt: "kupstinė šalmabudė",
      no: "eikehette",
      fa: "کلاه‌پارچه‌ای خوشه‌ای",
