        "https://lister.artsdatabanken.no/rodlisteforarter/2021/18625",
        "https://doi.org/10.1007/s10267-011-0128-1",
        "https://mykospol.sk/wp-content/uploads/2019/04/Spravodajca_c-302004.pdf"
